const entrada = $input.first().json;
const errores = [];

const idActivo = Number(entrada.params?.id_activo);
const body = entrada.body;

if (
  !entrada.params?.id_activo ||
  !Number.isSafeInteger(idActivo) ||
  idActivo <= 0
) {
  errores.push({
    campo: "id_activo",
    mensaje: "El identificador del activo debe ser un entero positivo."
  });
}

if (!body || typeof body !== "object" || Array.isArray(body)) {
  errores.push({
    campo: "body",
    mensaje: "El cuerpo de la solicitud debe ser un objeto JSON."
  });
}

const contenido = body?.contenido;

if (
  !contenido ||
  typeof contenido !== "object" ||
  Array.isArray(contenido)
) {
  errores.push({
    campo: "contenido",
    mensaje: "Debe enviarse un objeto contenido."
  });
} else if (
  typeof contenido.text !== "string" ||
  !contenido.text.trim()
) {
  errores.push({
    campo: "contenido.text",
    mensaje: "El texto del activo no puede estar vacío."
  });
}

if (
  typeof body?.motivo_cambio !== "string" ||
  !body.motivo_cambio.trim()
) {
  errores.push({
    campo: "motivo_cambio",
    mensaje: "Debes indicar el motivo de la edición."
  });
}

if (
  typeof body?.creado_por !== "string" ||
  !body.creado_por.trim()
) {
  errores.push({
    campo: "creado_por",
    mensaje: "Debes indicar quién realizó la edición."
  });
}

return [{
  json: {
    valido: errores.length === 0,
    errores,
    id_activo: idActivo,
    contenido: contenido ?? null,
    motivo_cambio: body?.motivo_cambio?.trim() ?? null,
    creado_por: body?.creado_por?.trim() ?? null
  }
}];

